CREATE TABLE P360_RECEIPTS (EVENT_ID VARCHAR(36) PRIMARY KEY, TYPE VARCHAR(40) NOT NULL, OWNER_ID VARCHAR(250) NOT NULL, ORDER_ID BIGINT NOT NULL, STORE_ID BIGINT NOT NULL, PROCESSED_AT TIMESTAMP WITH TIME ZONE NOT NULL, ARTIFACT VARCHAR(100) NOT NULL);
CREATE INDEX IDX_RECEIPT_OWNER ON P360_RECEIPTS(OWNER_ID);
